CREATE TABLE "Audit_Events" (
  "audit_event_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "action" VARCHAR(40) NOT NULL,
  "result" VARCHAR(30) NOT NULL,
  "order_id" INT,
  "payment_id" INT,
  "amount" DECIMAL(6,2),
  "actor" VARCHAR(40) NOT NULL,
  "occurred_at" TIMESTAMPTZ NOT NULL,
  "correlation_id" VARCHAR(80) NOT NULL,
  "operation_key" VARCHAR(120),
  CONSTRAINT "audit_event_action_allowed" CHECK ("action" IN ('PAYMENT_ATTEMPT', 'ORDER_COMPLETED')),
  CONSTRAINT "audit_event_result_allowed" CHECK ("result" IN ('CONFIRMED', 'REJECTED', 'FAILED', 'COMMITTED')),
  CONSTRAINT "audit_event_amount_positive" CHECK ("amount" IS NULL OR "amount" > 0)
);

CREATE INDEX "idx_audit_events_order_id" ON "Audit_Events" ("order_id");
CREATE INDEX "idx_audit_events_occurred_at" ON "Audit_Events" ("occurred_at" DESC, "audit_event_id" DESC);
